contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newOwner) public {
        address originalOwner = c.owner();
        bool callerIsOwner = (caller == originalOwner);
        bool reverted;
        if (callerIsOwner) {
            try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        } else {
            vm.prank(caller);
            try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        }
        address finalOwner = c.owner();
        if (callerIsOwner && newOwner != address(0)) {
            assert(!reverted && finalOwner == newOwner);
        } else if (callerIsOwner && newOwner == address(0)) {
            assert(reverted && finalOwner == originalOwner);
        } else {
            assert(reverted && finalOwner == originalOwner);
        }
    }
}

