contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address caller,
        address token,
        address rewards,
        uint32 pId,
        uint256 amount
    ) public {
        c.setCvxPoolInfo(pId, token, rewards);
        c.setOperator(address(this));

        uint256 beforeAllowance = IERC20(c.clpToken()).allowance(address(c), address(c.booster()));

        bool reverted;
        if (caller == address(this)) {
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = true;
        }

        uint256 afterAllowance = IERC20(c.clpToken()).allowance(address(c), address(c.booster()));

        assert(
            (caller == address(this))
                ? (!reverted || c.isCvxShutdown())
                    ? (afterAllowance == beforeAllowance + amount || reverted)
                    : (afterAllowance == beforeAllowance)
                : reverted
        );
    }
}

