contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewards) public {
        // Set up the reward pool that stakedBalance() calls through to.
        // setCvxPoolInfo is onlyOwner and this test contract is the owner of c.
        c.setCvxPoolInfo(uint32(0), address(0xdead), rewards);

        // Ensure the setup actually took effect (observable via the public getter).
        (, , address configuredRewards) = c.cvxPoolInfo();

        // The property only makes sense once the reward contract has been configured to
        // call through to; otherwise the external call itself would revert.
        require(configuredRewards != address(0), "reward pool not configured");

        // Before-value read through the same external entry point.
        uint256 beforeBalance = IBaseRewardPool(configuredRewards).balanceOf(address(c));

        // Deciding call on the contract under test.
        uint256 returned = c.stakedBalance();

        // The return value of the call must equal the balance reported by the
        // configured reward pool.
        assert(returned == beforeBalance);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewards) public {
        // Configure the reward pool that stakedBalance() will call through to.
        // c.cvxPoolInfo is a public struct with fields (address token, address rewards, uint32 pId).
        c.setCvxPoolInfo(uint32(0), address(0xdead), rewards);

        // Read the configured reward address back through the public getter.
        (, address configuredRewards, ) = c.cvxPoolInfo();

        // The rule is meaningful once the reward pool is set; otherwise the underlying call reverts.
        require(configuredRewards != address(0), "reward pool not configured");

        // Before-value, observed by calling the same external contract that c.stakedBalance() will call.
        uint256 reportedBalance = IBaseRewardPool(configuredRewards).balanceOf(address(c));

        // Deciding call: the contract under test reads its staked balance through the reward pool.
        uint256 returned = c.stakedBalance();

        // General rule: the returned value must be exactly what the configured reward pool reports.
        assert(returned == reportedBalance);
    }
}

