contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to, uint32 pId, address token, address rewards) public {
        require(amount > 0, "amount must be positive");

        // Configure the pool info as owner so that the call has a target.
        c.setCvxPoolInfo(pId, token, rewards);

        // Record whether this test contract is the operator or owner.
        address ownerAddr = c.owner();
        address operatorAddr = c.operator();
        bool callerIsOperatorOrOwner = (address(this) == ownerAddr) || (address(this) == operatorAddr);

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!callerIsOperatorOrOwner) {
            // A non-operator, non-owner caller must always be rejected.
            assert(reverted);
        } else {
            // The owner/operator path is only expected to succeed when the caller is the owner,
            // the requested amount exceeds the current CLP balance, and funds are not sent out.
            uint256 beforeBalance = c.clpToken().balanceOf(address(this));
            if (address(this) == ownerAddr && amount > beforeBalance && to == address(0)) {
                assert(!reverted);
            }
        }
    }

    receive() external payable {}
}

